		repository.init();
		if (seeded) {
			try (var seed = repository.getConnection()) {
				// Exercise ordinary map growth; the empty fixture separately covers initial-import admission.
				seed.add(Values.iri(NAMESPACE + "seed"), Values.iri(NAMESPACE + "p"), Values.literal("seed"));
			}
		}
		List<Transaction> createdTransactions = new CopyOnWriteArrayList<>();
		TransactionStartController starts = new TransactionStartController() {
			@Override
			Transaction createTransaction(Repository rep) throws ExecutionException, InterruptedException {
				Transaction transaction = super.createTransaction(rep);
				createdTransactions.add(transaction);
				return transaction;
			}
		};
