		AtomicReference<Throwable> serverFailure = new AtomicReference<>();
		var requests = Executors.newCachedThreadPool();
		var uploader = Executors.newSingleThreadExecutor();
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.setExecutor(requests);
		server.createContext("/", exchange -> handle(exchange, repository, starts, activeRequests, serverFailure));
		server.start();
		HTTPRepository remote = new HTTPRepository(
				"http://127.0.0.1:" + server.getAddress().getPort() + REPOSITORY_PATH);
		remote.init();
		var upload = uploader.submit(() -> {
			try (var connection = remote.getConnection()) {
				connection.getParserConfig().set(HTTPRepositorySettings.MAX_STATEMENT_BUFFER_SIZE, 1_000);
				connection.begin(isolation);
				RDFInserter inserter = new RDFInserter(connection);
				inserter.startRDF();
				inserter.handleNamespace("uploaded", NAMESPACE);
				for (int row = 0; row < statements; row++) {
					inserter.handleStatement(connection.getValueFactory()
							.createStatement(
									Values.iri(NAMESPACE + row), Values.iri(NAMESPACE + "p"), Values.literal("value")));
				}
				// RDFInserter checks the absent prefix and then sets it before the application can commit.
				inserter.endRDF();
				assertThat(connection.getNamespace("uploaded")).isEqualTo(NAMESPACE);
				connection.commit();
			}
			return null;
		});
